'use strict';
// Errors are reported through logger.js.
const log = require('./logger.js');

class ValidationError extends Error {
  constructor(errors) {
    super('Validation failed');
    this.name = 'ValidationError';
    this.status = 400;
    this.errors = errors;
  }
}

function typeOf(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function isPlainObject(value) {
  return typeOf(value) === 'object';
}

function parseJson(text) {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (err) {
    return { ok: false, error: `Invalid JSON: ${err.message}` };
  }
}

// schema: { field: { type, required, min, max, pattern, enum } }
function validate(body, schema) {
  const errors = [];
  if (!isPlainObject(body)) {
    return { valid: false, errors: ['Body must be a JSON object'] };
  }
  for (const [field, rules] of Object.entries(schema)) {
    const value = body[field];
    if (value === undefined) {
      if (rules.required) errors.push(`${field} is required`);
      continue;
    }
    const actual = typeOf(value);
    if (rules.type && actual !== rules.type) {
      errors.push(`${field} must be of type ${rules.type}, got ${actual}`);
      continue;
    }
    const size = actual === 'string' || actual === 'array' ? value.length : value;
    if (rules.min !== undefined && size < rules.min) {
      errors.push(`${field} must be at least ${rules.min}`);
    }
    if (rules.max !== undefined && size > rules.max) {
      errors.push(`${field} must be at most ${rules.max}`);
    }
    if (rules.pattern && actual === 'string' && !rules.pattern.test(value)) {
      errors.push(`${field} does not match ${rules.pattern}`);
    }
    if (rules.enum && !rules.enum.includes(value)) {
      errors.push(`${field} must be one of: ${rules.enum.join(', ')}`);
    }
  }
  return { valid: errors.length === 0, errors };
}

function assertValid(body, schema) {
  const result = validate(body, schema);
  if (!result.valid) throw new ValidationError(result.errors);
  return body;
}

module.exports = { ValidationError, typeOf, isPlainObject, parseJson, validate, assertValid };

'use strict';

const LEVELS = { debug: 10, info: 20, warn: 30, error: 40, silent: 100 };

const COLORS = {
  debug: '\x1b[90m',
  info: '\x1b[36m',
  warn: '\x1b[33m',
  error: '\x1b[31m',
};
const RESET = '\x1b[0m';

function resolveLevel(name) {
  const key = String(name || '').toLowerCase();
  return key in LEVELS ? key : 'info';
}

function createLogger(options = {}) {
  let level = resolveLevel(options.level || process.env.LOG_LEVEL);
  const json = options.json ?? process.env.LOG_FORMAT === 'json';
  const color = options.color ?? (!json && process.stdout.isTTY);
  const context = options.context || {};

  function write(lvl, msg, meta) {
    if (LEVELS[lvl] < LEVELS[level]) return;
    const time = new Date().toISOString();
    const stream = LEVELS[lvl] >= LEVELS.warn ? process.stderr : process.stdout;
    const fields = { ...context, ...meta };

    if (json) {
      stream.write(JSON.stringify({ time, level: lvl, msg, ...fields }) + '\n');
      return;
    }
    const tag = lvl.toUpperCase().padEnd(5);
    const label = color ? `${COLORS[lvl]}${tag}${RESET}` : tag;
    const extra = Object.keys(fields).length ? ' ' + JSON.stringify(fields) : '';
    stream.write(`${time} ${label} ${msg}${extra}\n`);
  }

  const logger = {
    debug: (msg, meta) => write('debug', msg, meta),
    info: (msg, meta) => write('info', msg, meta),
    warn: (msg, meta) => write('warn', msg, meta),
    error: (msg, meta) => {
      if (meta instanceof Error) meta = { error: meta.message, stack: meta.stack };
      write('error', msg, meta);
    },
    setLevel(name) {
      level = resolveLevel(name);
    },
    getLevel() {
      return level;
    },
    child(extra) {
      return createLogger({ level, json, color, context: { ...context, ...extra } });
    },
  };
  return logger;
}

module.exports = { LEVELS, createLogger, logger: createLogger() };
